import React, {
  useState,
  useRef,
  useEffect,
  useCallback,
  KeyboardEvent,
  ChangeEvent,
  MouseEvent,
  useMemo,
} from 'react';

interface AutocompleteOption {
  id: string;
  label: string;
  value: string;
}

interface AutocompleteProps {
  options: AutocompleteOption[];
  value?: string;
  onChange?: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  loading?: boolean;
  noOptionsText?: string;
  className?: string;
}

export const Autocomplete: React.FC<AutocompleteProps> = ({
  options = [],
  value = '',
  onChange,
  placeholder = 'Search...',
  disabled = false,
  loading = false,
  noOptionsText = 'No options found',
  className = '',
}) => {
  const [inputValue, setInputValue] = useState(value);
  const [isOpen, setIsOpen] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const [filteredOptions, setFilteredOptions] = useState<AutocompleteOption[]>([]);

  const inputRef = useRef<HTMLInputElement>(null);
  const listboxRef = useRef<HTMLUListElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Filter options based on input value
  useEffect(() => {
    if (!inputValue) {
      setFilteredOptions(options);
    } else {
      const filtered = options.filter(option =>
        option.label.toLowerCase().includes(inputValue.toLowerCase())
      );
      setFilteredOptions(filtered);
    }
    setHighlightedIndex(-1);
  }, [inputValue, options]);

  // Update internal state when external value changes
  useEffect(() => {
    setInputValue(value);
  }, [value]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside as any);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside as any);
    };
  }, []);

  // Handle keyboard navigation
  const handleKeyDown = useCallback((e: KeyboardEvent<HTMLInputElement>) => {
    if (disabled) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setIsOpen(true);
        setHighlightedIndex(prev => 
          prev < filteredOptions.length - 1 ? prev + 1 : prev
        );
        break;

      case 'ArrowUp':
        e.preventDefault();
        setHighlightedIndex(prev => (prev > 0 ? prev - 1 : -1));
        break;

      case 'Enter':
        e.preventDefault();
        if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
          const selectedOption = filteredOptions[highlightedIndex];
          setInputValue(selectedOption.label);
          onChange?.(selectedOption.value);
          setIsOpen(false);
        }
        break;

      case 'Escape':
        setIsOpen(false);
        setHighlightedIndex(-1);
        break;

      case 'Tab':
        setIsOpen(false);
        break;
    }
  }, [disabled, filteredOptions, highlightedIndex, onChange]);

  const handleInputChange = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    setInputValue(newValue);
    setIsOpen(true);
  }, []);

  const handleOptionClick = useCallback((option: AutocompleteOption) => {
    setInputValue(option.label);
    onChange?.(option.value);
    setIsOpen(false);
    inputRef.current?.focus();
  }, [onChange]);

  const handleClear = useCallback((e: MouseEvent) => {
    e.stopPropagation();
    setInputValue('');
    onChange?.('');
    setIsOpen(false);
    inputRef.current?.focus();
  }, [onChange]);

  const handleToggleDropdown = useCallback(() => {
    if (!disabled) {
      setIsOpen(!isOpen);
      if (!isOpen) {
        inputRef.current?.focus();
      }
    }
  }, [disabled, isOpen]);

  // Memoize accessibility attributes
  const listBoxId = useMemo(() => `autocomplete-listbox-${Math.random().toString(36).substr(2, 9)}`, []);
  const activeDescendant = useMemo(() => 
    highlightedIndex >= 0 ? `autocomplete-option-${highlightedIndex}` : undefined,
    [highlightedIndex]
  );

  return (
    <div 
      ref={containerRef}
      className={`autocomplete-container ${className}`}
      role="combobox"
      aria-expanded={isOpen}
      aria-haspopup="listbox"
      aria-owns={listBoxId}
    >
      <div className="autocomplete-input-wrapper">
        <input
          ref={inputRef}
          type="text"
          value={inputValue}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          onFocus={() => setIsOpen(true)}
          placeholder={placeholder}
          disabled={disabled}
          role="combobox"
          aria-autocomplete="list"
          aria-controls={listBoxId}
          aria-activedescendant={activeDescendant}
          className="autocomplete-input"
        />
        {inputValue && (
          <button
            type="button"
            onClick={handleClear}
            aria-label="Clear selection"
            className="autocomplete-clear-button"
          >
            ×
          </button>
        )}
        <button
          type="button"
          onClick={handleToggleDropdown}
          aria-label={isOpen ? "Close suggestions" : "Open suggestions"}
          className="autocomplete-toggle-button"
          disabled={disabled}
        >
          {loading ? (
            <span className="autocomplete-spinner" aria-label="Loading">↻</span>
          ) : (
            <span>{isOpen ? '▲' : '▼'}</span>
          )}
        </button>
      </div>

      {isOpen && (
        <ul
          ref={listboxRef}
          id={listBoxId}
          role="listbox"
          className="autocomplete-dropdown"
        >
          {filteredOptions.length === 0 ? (
            <li 
              role="option" 
              className="autocomplete-no-options"
            >
              {noOptionsText}
            </li>
          ) : (
            filteredOptions.map((option, index) => (
              <li
                key={option.id}
                id={`autocomplete-option-${index}`}
                role="option"
                aria-selected={index === highlightedIndex}
                onClick={() => handleOptionClick(option)}
                className={`autocomplete-option ${
                  index === highlightedIndex ? 'autocomplete-option-highlighted' : ''
                }`}
              >
                {option.label}
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  );
};

// Default export for the component
export default Autocomplete;
