/* CSS Styles */
.autocomplete-container {
  position: relative;
  width: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.autocomplete-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: white;
}

.autocomplete-input {
  flex: 1;
  padding: 8px 12px;
  border: none;
  outline: none;
  font-size: 16px;
  background: transparent;
}

.autocomplete-input:focus {
  box-shadow: 0 0 0 2px #007cba;
}

.autocomplete-clear-button,
.autocomplete-toggle-button {
  background: none;
  border: none;
  padding: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #555;
  font-size: 16px;
}

.autocomplete-clear-button:hover,
.autocomplete-toggle-button:hover {
  background-color: #f5f5f5;
  border-radius: 4px;
}

.autocomplete-clear-button:focus,
.autocomplete-toggle-button:focus {
  outline: 2px solid #007cba;
  outline-offset: -2px;
}

.autocomplete-dropdown {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  z-index: 1000;
  margin: 4px 0 0;
  padding: 0;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: white;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
  max-height: 200px;
  overflow-y: auto;
  list-style: none;
}

.autocomplete-option {
  padding: 8px 12px;
  cursor: pointer;
  border-bottom: 1px solid #eee;
}

.autocomplete-option:last-child {
  border-bottom: none;
}

.autocomplete-option-highlighted {
  background-color: #007cba;
  color: white;
}

.autocomplete-option:hover:not(.autocomplete-option-highlighted) {
  background-color: #f5f5f5;
}

.autocomplete-no-options {
  padding: 16px 12px;
  text-align: center;
  color: #666;
  font-style: italic;
}

.autocomplete-spinner {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  100% {
    transform: rotate(360deg);
  }
}

/* Disabled state */
.autocomplete-container[aria-disabled="true"] .autocomplete-input,
.autocomplete-container[aria-disabled="true"] .autocomplete-toggle-button {
  opacity: 0.5;
  cursor: not-allowed;
}
